import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.il0noOp3.js";const k=JSON.parse('{"title":"Azure DevOps","description":"Inventory Azure DevOps projects, pipelines, service connections, repositories, and agent pools alongside your Azure resources.","frontmatter":{"description":"Inventory Azure DevOps projects, pipelines, service connections, repositories, and agent pools alongside your Azure resources."},"headers":[],"relativePath":"automation-guide/azure-devops.md","filePath":"automation-guide/azure-devops.md"}'),n={name:"automation-guide/azure-devops.md"};function r(o,s,l,h,p,d){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="azure-devops" tabindex="-1">Azure DevOps <a class="header-anchor" href="#azure-devops" aria-label="Permalink to &quot;Azure DevOps&quot;">​</a></h1><p><code>-IncludeDevOps</code> extends a scan to cover Azure DevOps, so a single report holds both the infrastructure and the pipelines that deploy to it.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Five worksheets are added: <strong>ADO Projects</strong>, <strong>ADO Pipelines</strong>, <strong>ADO Service Connections</strong>, <strong>ADO Repositories</strong>, and <strong>ADO Agent Pools</strong>.</p><h2 id="why-it-is-opt-in" tabindex="-1">Why it is opt-in <a class="header-anchor" href="#why-it-is-opt-in" aria-label="Permalink to &quot;Why it is opt-in&quot;">​</a></h2><p>Azure DevOps is a separate service with its own authorization model — a fourth permission system, unrelated to both Azure RBAC and Entra directory roles. An identity with Owner on every Azure subscription and Global Administrator in Entra still gets zero rows here without Azure DevOps org/project membership. An inventory run should not stall or fail on it by default, so collection only happens when you ask for it. The rest of the scan is unaffected either way.</p><p>Read-only <strong>project-level</strong> access — no organization administrator role — is sufficient. See <a href="./../guide/permissions.html">Permissions</a> for how this fits alongside the ARM and Entra grants when you&#39;re assembling a full access request.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>By default, no personal access token is needed. AzureScout requests an Entra access token for the Azure DevOps resource using the identity already signed in for the Azure inventory:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Connect-AzAccount</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Supply a PAT when the Azure identity and the Azure DevOps identity differ:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DevOpsPat $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ADO_PAT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>A PAT needs <strong>read</strong> scope on: Project and Team, Build, Release, Code, Service Connections, and Agent Pools. Nothing is ever written — every call is a GET.</p><div class="warning custom-block"><p class="custom-block-title">Never put a PAT in a script file</p><p>Pass it from an environment variable or a secret store. A PAT committed to a repository is a credential leak, and AzureScout&#39;s own hard rules forbid secrets in committed files.</p></div><h2 id="choosing-organizations" tabindex="-1">Choosing organizations <a class="header-anchor" href="#choosing-organizations" aria-label="Permalink to &quot;Choosing organizations&quot;">​</a></h2><p>Organizations are discovered from the signed-in profile when you do not name them:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Discovers every organization the signed-in user belongs to</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>A service principal has no profile to enumerate, so unattended runs must name their organizations explicitly:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AppId </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;client-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Secret </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;secret&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DevOpsOrganization </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contoso&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fabrikam&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="what-gets-collected" tabindex="-1">What gets collected <a class="header-anchor" href="#what-gets-collected" aria-label="Permalink to &quot;What gets collected&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Worksheet</th><th>Contents</th></tr></thead><tbody><tr><td>ADO Projects</td><td>Name, description, state, visibility, revision, last update</td></tr><tr><td>ADO Pipelines</td><td>Name, owning project, folder, configuration type, YAML path, revision</td></tr><tr><td>ADO Service Connections</td><td>Name, type, authorization scheme, service principal, target subscription, in-scope flag</td></tr><tr><td>ADO Repositories</td><td>Name, owning project, default branch, size, disabled flag, web URL</td></tr><tr><td>ADO Agent Pools</td><td>Name, hosting model, pool type, agent count, auto-provision, owner</td></tr></tbody></table><h2 id="the-subscription-cross-reference" tabindex="-1">The subscription cross-reference <a class="header-anchor" href="#the-subscription-cross-reference" aria-label="Permalink to &quot;The subscription cross-reference&quot;">​</a></h2><p><strong>ADO Service Connections</strong> is the sheet worth reading first. For every Azure Resource Manager connection it records the target subscription and, crucially, whether that subscription is one the current scan covers:</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Target Subscription ID</code></td><td>The subscription the connection can reach</td></tr><tr><td><code>Subscription In Scope</code></td><td><code>Yes</code> when that subscription is part of this scan</td></tr><tr><td><code>Credential Free</code></td><td><code>Yes</code> for workload identity federation; <code>No</code> for a secret or certificate</td></tr></tbody></table><p>A <code>Subscription In Scope</code> of <code>Yes</code> means a pipeline in that project has a credentialled path into infrastructure this report covers — that is the pairing worth reviewing. Rows are highlighted in the workbook.</p><p><code>Credential Free</code> of <code>No</code> marks a connection still authenticating with a secret or certificate, each of which expires and has to be rotated. Migrating those to workload identity federation removes the rotation burden entirely.</p><p><strong>ADO Agent Pools</strong> highlights self-hosted pools for the same reason: those are the agents you patch, secure, and pay for, as opposed to the Microsoft-hosted ones.</p><h2 id="combining-with-other-options" tabindex="-1">Combining with other options <a class="header-anchor" href="#combining-with-other-options" aria-label="Permalink to &quot;Combining with other options&quot;">​</a></h2><p><code>-IncludeDevOps</code> composes with everything else:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Azure DevOps plus Entra ID plus ARM</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope All </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Azure DevOps data in JSON for downstream processing</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat Json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Two organizations, named run folder</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeDevOps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DevOpsOrganization </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contoso&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fabrikam&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RunName </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;devops-audit&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Azure DevOps collectors live in the <code>Management</code> category, so <code>-Category Management</code> includes them and any other category filter excludes them.</p><h2 id="partial-access-is-normal" tabindex="-1">Partial access is normal <a class="header-anchor" href="#partial-access-is-normal" aria-label="Permalink to &quot;Partial access is normal&quot;">​</a></h2><p>An identity commonly holds project read but not service connection read. AzureScout treats a 401 or 403 on one endpoint as a skip for that slice and carries on with the rest — you get the projects and pipelines even when the service connections are denied. Run with <code>-Debug</code> to see exactly which endpoints were refused.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;No Azure DevOps organizations could be discovered&quot;</td><td>Service principal, or a user with no profile</td><td>Pass <code>-DevOpsOrganization</code></td></tr><tr><td>&quot;Could not acquire an Azure DevOps token&quot;</td><td>Not signed in, or the sign-in cannot reach Azure DevOps</td><td><code>Connect-AzAccount</code>, or pass <code>-DevOpsPat</code></td></tr><tr><td>ADO Service Connections sheet missing</td><td>Identity lacks service connection read</td><td>Grant the scope, or accept the partial result</td></tr><tr><td>All <code>Subscription In Scope</code> values are <code>No</code></td><td>Connections point at subscriptions outside this scan</td><td>Widen the scan, or omit <code>-SubscriptionID</code></td></tr><tr><td>Organization skipped with &quot;No project access&quot;</td><td>Identity is not a member of that organization</td><td>Check membership, or drop it from <code>-DevOpsOrganization</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./github-actions.html">GitHub Actions</a> — running AzureScout itself from a pipeline</li><li><a href="./automation.html">Azure Automation Account</a> — scheduled unattended runs</li><li><a href="./../reference/category-reference.html">Category Reference</a> — where these collectors sit</li><li><a href="./../guide/authentication.html">Authentication</a> — Azure sign-in methods</li></ul>`,37)])])}const u=e(n,[["render",r]]);export{k as __pageData,u as default};
